func:
// Recebe o JSON publicado pelo app17-7 em FIAPIoT/motor/multiclasse.
// No MQTT-in em datatype "json" o payload ja chega como objeto; protegemos
// mesmo assim contra string.
let p = msg.payload;
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) { node.error("Payload nao e JSON valido", msg); return null; }
}

// A turma inteira publica no mesmo broker e no mesmo topico: o device
// (o MQTT_CLIENT_ID do firmware) diz de quem e a janela. Escreva aqui o
// nome da SUA placa para gravar so as suas janelas. Vazio = grava todas.
const MEU_DEVICE = "";
if (MEU_DEVICE && p.device !== MEU_DEVICE) {
    node.status({ fill: "grey", shape: "ring", text: "ignorado: " + p.device });
    return null;
}

// Janela sem label nao e do dataset: e uma placa em modo de inferencia
// publicando no mesmo topico. Nao grava (senao vira a classe "desconhecido").
if (!p.label) {
    node.status({ fill: "grey", shape: "ring", text: "sem label (inferencia): " + p.device });
    return null;
}

// label vem da SEQUENCIA CICLICA do proprio ESP32 (avancada pelo botao 18).
const label = p.label || "desconhecido";
// rodada identifica a VOLTA completa pela sequencia -- e o group do
// LeaveOneGroupOut no notebook, por isso vira tag (como no app17-6), nao field.
const rodada = String(p.rodada != null ? p.rodada : "00");

// As 8 features (mean_*/std_* dos 3 eixos + std_mag + p2p_mag) + janela
// (indice dentro da rodada) + ts_ms (tempo do ESP32, so para referencia -- o
// horario do ponto e o da chegada no Node-RED).
const fields = {
    janela:      Number(p.janela),
    ts_ms:       Number(p.ts_ms) || 0,
    mean_ax:     Number(p.mean_ax),
    mean_ay:     Number(p.mean_ay),
    mean_az:     Number(p.mean_az),
    std_ax:      Number(p.std_ax),
    std_ay:      Number(p.std_ay),
    std_az:      Number(p.std_az),
    std_mag:     Number(p.std_mag),
    p2p_mag:     Number(p.p2p_mag)
};

// label e rodada como TAGS: e o que o notebook usa pra agrupar
// (groupby label/rodada) e pro LeaveOneGroupOut por rodada.
const tags = {
    label:  label,
    rodada: rodada,
    device: p.device || "esp32"
};

node.status({ fill: "green", shape: "dot",
    text: label + " r" + rodada + " | std_mag=" + (isFinite(fields.std_mag) ? fields.std_mag.toFixed(3) : "?") });

// node-red-contrib-influxdb: payload = [fields, tags]
msg.payload = [fields, tags];
return msg;
